INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Betroffenenrechte > Recht auf Widerspruch
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gewährt Art. 21 DSGVO Betroffenen das Recht, der Verarbeitung ihrer personenbezogenen Daten zu widersprechen?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 21 DSGVO garantiert das Widerspruchsrecht"}, {"text": "Nein", "correct": false, "because": "Recht ist gesetzlich verankert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Recht auf Widerspruch jederzeit ohne Angabe von Gründen ausgeübt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Gründe sind nötig, außer bei Direktwerbung"}, {"text": "Ja", "correct": false, "because": "Begründung erforderlich außer bei Werbung"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Unternehmen bei einem Widerspruch die Verarbeitung sofort einstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Verarbeitung muss eingestellt werden, es sei denn, zwingende Gründe sprechen dagegen"}, {"text": "Nein", "correct": false, "because": "Einstellung ist Pflicht bei berechtigtem Widerspruch"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Betroffene ihr Recht auf Widerspruch gegen Direktwerbung ohne Einschränkung ausüben?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 21 Abs. 2 DSGVO erlaubt uneingeschränkten Widerspruch bei Direktwerbung"}, {"text": "Nein", "correct": false, "because": "Widerspruch bei Direktwerbung absolut"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Recht auf Widerspruch gemäß Art. 21 DSGVO an eine Frist gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Keine spezifische Frist für die Ausübung vorgesehen"}, {"text": "Ja", "correct": false, "because": "Widerspruch jederzeit möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was erlaubt das Recht auf Widerspruch gemäß Art. 21 DSGVO Betroffenen?', 2, '[{"text": "Verarbeitung ihrer Daten zu verhindern", "correct": true, "because": "Art. 21 DSGVO erlaubt Widerspruch gegen Verarbeitung"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grund berechtigt Betroffene automatisch zum Widerspruch gemäß Art. 21 DSGVO?', 3, '[{"text": "Direktwerbung", "correct": true, "because": "Art. 21 Abs. 2 DSGVO gibt absolutes Widerspruchsrecht"}, {"text": "Vertragserfüllung", "correct": false, "because": "Begründung nötig"}, {"text": "Öffentliches Interesse", "correct": false, "because": "Zwingende Gründe können überwiegen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frist haben Unternehmen, um auf ein Widerspruchsverlangen zu reagieren?', 2, '[{"text": "Einen Monat", "correct": true, "because": "Art. 12 Abs. 3 DSGVO setzt eine Monatsfrist"}, {"text": "Drei Monate", "correct": false, "because": "Zu lang"}, {"text": "Keine Frist", "correct": false, "because": "Frist ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme müssen Unternehmen bei einem Widerspruch gegen Direktwerbung ergreifen?', 2, '[{"text": "Verarbeitung unverzüglich einstellen", "correct": true, "because": "Art. 21 Abs. 3 DSGVO fordert sofortige Einstellung"}, {"text": "Daten weiterverarbeiten", "correct": false, "because": "Verstoß gegen DSGVO"}, {"text": "Daten archivieren", "correct": false, "because": "Nicht vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei Nichtbeachtung des Rechts auf Widerspruch?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 21 strafbar"}, {"text": "Systemausfall", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Nicht relevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Gründe berechtigen Betroffene zum Widerspruch nach Art. 21 DSGVO?', 4, '[{"text": "Direktwerbung", "correct": true, "because": "Art. 21 Abs. 2"}, {"text": "Besondere Situation des Betroffenen", "correct": true, "because": "Art. 21 Abs. 1"}, {"text": "Interessenabwägung", "correct": true, "because": "Art. 21 Abs. 1 bei berechtigtem Interesse"}, {"text": "Vertragserfüllung", "correct": false, "because": "Kein Widerspruchsgrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen müssen Unternehmen bei einem Widerspruch ergreifen?', 3, '[{"text": "Verarbeitung einstellen", "correct": true, "because": "Pflicht bei berechtigtem Widerspruch"}, {"text": "Betroffene informieren", "correct": true, "because": "Pflicht nach Art. 21 Abs. 4"}, {"text": "Begründung bei Ablehnung", "correct": true, "because": "Zwingende Gründe angeben"}, {"text": "Daten weiterverarbeiten", "correct": false, "because": "Nur bei zwingenden Gründen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ausnahmen können den Widerspruch gemäß Art. 21 DSGVO überwiegen?', 4, '[{"text": "Zwingende schutzwürdige Gründe", "correct": true, "because": "Art. 21 Abs. 1"}, {"text": "Gesetzliche Verpflichtungen", "correct": true, "because": "Art. 21 Abs. 1"}, {"text": "Öffentliches Interesse", "correct": true, "because": "Art. 21 Abs. 1"}, {"text": "Technische Präferenzen", "correct": false, "because": "Keine Ausnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen das Recht auf Widerspruch haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen DSGVO strafbar"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Softwareplanung unterstützen das Recht auf Widerspruch?', 3, '[{"text": "Widerspruchsfunktion integrieren", "correct": true, "because": "Erleichtert Ausübung"}, {"text": "Automatisierte Verarbeitungseinstellung", "correct": true, "because": "Effiziente Umsetzung"}, {"text": "Dokumentation der Widersprüche", "correct": true, "because": "Nachweisbarkeit"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht DSGVO"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Recht auf Widerspruch gilt gegen Direktwerbung ohne Einschränkung. b) Es erfordert immer eine Begründung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Direktwerbung ja, Begründung nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unternehmen müssen bei Widerspruch die Verarbeitung einstellen. b) Es gibt keine Ausnahmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einstellung ja, Ausnahmen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Recht auf Widerspruch kann jederzeit ausgeübt werden. b) Verstöße führen nie zu Bußgeldern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Jederzeit ja, Bußgelder möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Bei Direktwerbung ist der Widerspruch absolut. b) Zwingende Gründe können Widersprüche überwiegen.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Direktwerbung absolut, sonst Gründe möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Software muss Widerspruchsfunktionen bereitstellen. b) Widerspruch gilt nur bei unrechtmäßiger Verarbeitung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funktion ja, nicht nur unrechtmäßig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

